def choose_move(observation):
    w = observation["grid_width"]
    h = observation["grid_height"]
    sx, sy = observation["self_position"]
    ox, oy = observation["opponent_position"]

    obstacles = set()
    for p in observation.get("obstacles") or []:
        if isinstance(p, (list, tuple)) and len(p) >= 2:
            x, y = p[0], p[1]
            if 0 <= x < w and 0 <= y < h:
                obstacles.add((x, y))

    resources = []
    for r in observation.get("resources") or []:
        if isinstance(r, (list, tuple)) and len(r) >= 2:
            x, y = r[0], r[1]
            if 0 <= x < w and 0 <= y < h and (x, y) not in obstacles:
                resources.append((x, y))

    def man(x1, y1, x2, y2):
        return abs(x1 - x2) + abs(y1 - y2)

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1), (0, 0)]
    if not resources:
        tx, ty = w // 2, h // 2
        best = None
        for dx, dy in dirs:
            nx, ny = sx + dx, sy + dy
            if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
                sc = man(nx, ny, tx, ty)
                if best is None or sc < best[0]:
                    best = (sc, dx, dy)
        return [best[1], best[2]] if best else [0, 0]

    best_r = None
    best_score = None
    for rx, ry in resources:
        ds = man(sx, sy, rx, ry)
        do = man(ox, oy, rx, ry)
        # prefer resources we can reach first; break ties by closer to self, then position
        score = (0 if ds <= do else 1, ds, rx, ry)
        if best_score is None or score < best_score:
            best_score = score
            best_r = (rx, ry)

    rx, ry = best_r
    want_opp_away = (best_score[0] == 1)
    if want_opp_away:
        ax = 0 if ox == sx else (1 if ox < sx else -1)
        ay = 0 if oy == sy else (1 if oy < sy else -1)
        tx, ty = sx + ax, sy + ay
    else:
        tx, ty = rx, ry

    best = None
    for dx, dy in dirs:
        nx, ny = sx + dx, sy + dy
        if 0 <= nx < w and 0 <= ny < h and (nx, ny) not in obstacles:
            sc = man(nx, ny, tx, ty)
            if best is None or sc < best[0]:
                best = (sc, dx, dy)
    return [best[1], best[2]] if best else [0, 0]

